const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const months=['jan','feb','mrt','apr','mei','jun','jul','aug','sep','okt','nov','dec'];
const monthNames=['januari','februari','maart','april','mei','juni','juli','augustus','september','oktober','november','december'];
const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Brussels',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
function formatChecked(iso){const [year,month,day]=iso.split('-');return `${Number(day)} ${monthNames[Number(month)-1]} ${year}`}
function scoreOf(f){return f.score&&Number.isFinite(f.score.home)&&Number.isFinite(f.score.away)?f.score:null}
function scoreLabel(s){return `${s.home} – ${s.away}`}
function ourResult(f){const s=scoreOf(f);if(!s)return '';const ours=f.home==='De Zwaluw'?s.home:s.away;const theirs=f.home==='De Zwaluw'?s.away:s.home;return ours>theirs?'win':ours<theirs?'loss':'draw'}
function isHome(f){return f.home==='De Zwaluw'}
function isPast(f){return Boolean(scoreOf(f))||f.date<today}
function mapsUrl(f){return 'https://www.google.com/maps/dir/?api=1&destination='+encodeURIComponent(f.address)}
function routeLink(f,label){return `<a class="route-link" href="${mapsUrl(f)}" target="_blank" rel="noopener" aria-label="Route naar ${escapeHTML(f.venue)}">${label}</a>`}
function fixtureHTML(f,extraClass=''){const [year,month,day]=f.date.split('-');const home=isHome(f);const past=isPast(f);const maps=mapsUrl(f);const score=scoreOf(f);const result=ourResult(f);const middle=score?`<span class="score score-${result}">${scoreLabel(score)}</span>`:'<span class="vs">vs</span>';const note=score?`Uitslag ${scoreLabel(score)} · 22u · Volgens ATC-wedstrijdblad.`:`22u · Nog geen uitslag bij controle op ${formatChecked(clubData.checked)}.`;const route=home?'':routeLink(f,'Route');const venueExtra=`<small>${score?scoreLabel(score):'22u'}</small>`;return `<details class="fixture${past?' past':''}${extraClass}"><summary><time class="fixture-date" datetime="${f.date}"><strong>${day}</strong><span>${months[Number(month)-1]} ${year}</span></time><div><div class="fixture-teams"><span class="${home?'ours':''}">${escapeHTML(f.home)}</span>${middle}<span class="${!home?'ours':''}">${escapeHTML(f.away)}</span></div><div class="fixture-meta"><span class="${f.type==='beker'?'cup-tag':'competition'}">${f.type==='beker'?'BEKER VAN ATC':'COMPETITIE · 1A'}</span><span>·</span><span>${home?'THUIS':'UIT'}</span>${past?'<span class="played-tag">Gespeeld</span>':''}${route}</div></div><div class="venue">${escapeHTML(f.venue)}${venueExtra}</div><span class="fixture-toggle" aria-hidden="true">＋</span></summary><div class="fixture-detail"><p><strong>${escapeHTML(f.venue)}</strong><br>${escapeHTML(f.address)}<br>${note}</p><div class="fixture-links">${home?'':`<a href="${maps}" target="_blank" rel="noopener">Route ↗</a>`}<a href="${f.url}" target="_blank" rel="noopener">Wedstrijdblad ATC ↗</a></div></div></details>`}
function bindRouteLinks(root){root.querySelectorAll('.route-link').forEach(link=>{['click','pointerdown'].forEach(type=>link.addEventListener(type,event=>event.stopPropagation()))})}
function panelHTML(list,empty,extra){const rows=list.length?list.map(f=>fixtureHTML(f,extra&&extra(f)||'')).join(''):`<p class="empty">${empty}</p>`;return `<div class="calendar-caption"><span>DATUM / WEDSTRIJD</span><span>LOCATIE</span></div>${rows}`}
function resultCountLabel(tab,n){
 if(tab==='upcoming')return n===1?'wedstrijd nog te spelen':'wedstrijden nog te spelen';
 if(tab==='played')return n===1?'gespeelde wedstrijd':'gespeelde wedstrijden';
 return 'spelers in het klassement';
}
function rankedPlayers(){
 return [...clubData.players].sort((a,b)=>b.points-a.points||String(a.display||a.name).localeCompare(b.display||b.name,'nl'));
}
function klassementHTML(){
 const rows=rankedPlayers();
 const top=Math.max(0,...rows.map(p=>Number(p.points)||0));
 let lastPoints=null,lastRank=0;
 return `<ol class="klassement">${rows.map((p,i)=>{
  const points=Number(p.points)||0;
  const rank=points===lastPoints?lastRank:i+1;
  lastPoints=points;lastRank=rank;
  const lead=points===top&&top>0;
  const photo=lead&&p.crown?p.crown:p.photo;
  const name=escapeHTML(p.display||p.name);
  const image=photo?`<img class="klassement-photo" src="${photo}" width="160" height="160" alt="${name}"${lead?'':' loading="lazy"'}>`:`<span class="klassement-photo is-empty" aria-hidden="true">${escapeHTML((p.display||p.name).split(' ').map(w=>w[0]).join('').slice(0,2))}</span>`;
  return `<li class="klassement-row${lead?' is-lead':''}"><span class="klassement-rank">${String(rank).padStart(2,'0')}</span>${image}<span class="klassement-name">${name}</span><span class="klassement-points">${points} <small>pt</small></span></li>`;
 }).join('')}</ol>`;
}
function selectCalendarTab(root,name){
 const tabs=[...root.querySelectorAll('[role="tab"]')];
 if(!tabs.length)return;
 tabs.forEach(tab=>{
  const on=tab.dataset.tab===name;
  tab.setAttribute('aria-selected',String(on));
  tab.tabIndex=on?0:-1;
  const panel=root.querySelector('#'+tab.getAttribute('aria-controls'));
  if(panel)panel.hidden=!on;
 });
 const active=tabs.find(tab=>tab.dataset.tab===name)||tabs[0];
 const n=Number(active.dataset.count||0);
 const count=document.querySelector('#result-count');
 if(count)count.textContent=`${n} ${resultCountLabel(active.dataset.tab,n)} · Seizoen 2026–2027`;
}
function bindCalendarTabs(root){
 const tabs=[...root.querySelectorAll('[role="tab"]')];
 tabs.forEach(tab=>{
  tab.addEventListener('click',()=>selectCalendarTab(root,tab.dataset.tab));
  tab.addEventListener('keydown',event=>{
   const keys={ArrowRight:1,ArrowLeft:-1,Home:'start',End:'end'};
   const move=keys[event.key];
   if(move==null)return;
   event.preventDefault();
   const next=move==='start'?tabs[0]:move==='end'?tabs[tabs.length-1]:tabs[(tabs.indexOf(tab)+move+tabs.length)%tabs.length];
   next.focus();
   selectCalendarTab(root,next.dataset.tab);
  });
 });
}
function renderFixtures(){
 const fixtures=clubData.fixtures;
 const past=fixtures.filter(isPast);
 const upcoming=fixtures.filter(f=>!isPast(f));
 const nextUp=upcoming[0];
 const root=document.querySelector('#fixtures');
 root.innerHTML=`<div class="calendar-tabs" role="tablist" aria-label="Wedstrijden en klassement"><button type="button" role="tab" id="tab-upcoming" data-tab="upcoming" data-count="${upcoming.length}" aria-selected="true" aria-controls="panel-upcoming" tabindex="0">Nog te spelen <span>${upcoming.length}</span></button><button type="button" role="tab" id="tab-played" data-tab="played" data-count="${past.length}" aria-selected="false" aria-controls="panel-played" tabindex="-1">Gespeeld <span>${past.length}</span></button><button type="button" role="tab" id="tab-klassement" data-tab="klassement" data-count="${clubData.players.length}" aria-selected="false" aria-controls="klassement" tabindex="-1">Klassement</button></div><div id="panel-upcoming" class="calendar-panel" role="tabpanel" aria-labelledby="tab-upcoming">${panelHTML(upcoming,'Geen wedstrijden meer te spelen in deze kalender.',f=>f===nextUp?' next':'')}</div><div id="panel-played" class="calendar-panel" role="tabpanel" hidden aria-labelledby="tab-played">${panelHTML(past,'Nog geen gespeelde wedstrijden in deze kalender.')}</div><div id="klassement" class="calendar-panel" role="tabpanel" hidden aria-labelledby="tab-klassement">${klassementHTML()}</div>`;
 const count=document.querySelector('#result-count');
 if(count)count.textContent=`${upcoming.length} ${resultCountLabel('upcoming',upcoming.length)} · Seizoen 2026–2027`;
 const start=typeof location!=='undefined'&&location.hash==='#klassement'?'klassement':'upcoming';
 selectCalendarTab(root,start);
 bindRouteLinks(root);
 bindCalendarTabs(root);
}
renderFixtures();
window.addEventListener('hashchange',()=>{const root=document.querySelector('#fixtures');if(root&&location.hash==='#klassement')selectCalendarTab(root,'klassement')});
document.querySelectorAll('.cup-match').forEach(card=>{const fixture=clubData.fixtures.find(f=>f.url===card.href);const score=fixture&&scoreOf(fixture);if(!score)return;const heading=card.querySelector('h3');if(heading)heading.innerHTML=`${escapeHTML(fixture.home)} <span class="cup-score score-${ourResult(fixture)}">${scoreLabel(score)}</span> ${escapeHTML(fixture.away)}`});
const snapshot=document.querySelector('.snapshot');if(snapshot)snapshot.textContent=`Kalenderstand: ${formatChecked(clubData.checked)} · Aanvang 22u.`;
const next=clubData.fixtures.find(f=>!scoreOf(f)&&f.date>=today)||clubData.fixtures.find(f=>f.date>=today);
if(next){const [year,month,day]=next.date.split('-');const away=!isHome(next);document.querySelector('.match-label p').innerHTML=(next.type==='beker'?'BEKER VAN ATC':'COMPETITIE · 1A')+' <span>'+(away?'UIT':'THUIS')+'</span>';document.querySelector('.next-teams').innerHTML=`${isHome(next)?'<strong>De Zwaluw</strong>':escapeHTML(next.home)} <span>vs</span> ${!isHome(next)?'<strong>De Zwaluw</strong>':escapeHTML(next.away)}`;document.querySelector('.next-date').innerHTML=`<strong>${day} ${months[Number(month)-1].toUpperCase()}</strong><span>Vrijdag · ${year}</span>`;const nextLink=document.querySelector('.next-match .round-link');if(away){nextLink.href=mapsUrl(next);nextLink.classList.add('is-route');nextLink.textContent='Route';nextLink.setAttribute('aria-label',`Route naar ${next.venue}`)}else{nextLink.href=next.url;nextLink.classList.remove('is-route');nextLink.textContent='↗';nextLink.setAttribute('aria-label',`${next.home} tegen ${next.away} op ATC`)}}else{document.querySelector('.next-match').innerHTML='<div><p class="eyebrow">SEIZOEN 2026–2027</p><p>Geen latere bevestigde wedstrijd in deze kalender. <a class="text-link" href="https://www.atc-tafelvoetbal.be/clubs/186" target="_blank" rel="noopener">Bekijk ATC voor nieuwe data ↗</a></p></div>'}
const reduced=matchMedia('(prefers-reduced-motion: reduce)');let motionEnabled=!reduced.matches;
const motionButton=document.createElement('button');motionButton.className='motion-control';document.querySelector('footer').append(motionButton);
function motionState(){document.documentElement.classList.toggle('no-motion',!motionEnabled);motionButton.textContent=motionEnabled?'Beweging aan':'Beweging uit';motionButton.setAttribute('aria-label',motionEnabled?'Animaties uitschakelen':'Animaties inschakelen');motionButton.setAttribute('aria-pressed',String(motionEnabled))}motionState();motionButton.addEventListener('click',()=>{motionEnabled=!motionEnabled;motionState()});reduced.addEventListener('change',e=>{motionEnabled=!e.matches;motionState()});
const hero=document.querySelector('.hero'),bird=document.querySelector('.hero-art img');
hero.addEventListener('pointermove',e=>{if(!motionEnabled||e.pointerType!=='mouse')return;const rect=hero.getBoundingClientRect();const x=(e.clientX-rect.left)/rect.width-.5,y=(e.clientY-rect.top)/rect.height-.5;bird.style.transform=`translate(${x*26}px,${y*22}px) rotate(${x*1.8}deg) scale(1.015)`});hero.addEventListener('pointerleave',()=>{bird.style.transform='none'});
const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){if(motionEnabled)entry.target.classList.add('reveal');observer.unobserve(entry.target)}}),{threshold:.12});document.querySelectorAll('.section-title,.cup-intro,.cup-fixtures,.standings-intro,.team-heading,.home-name,.home-address').forEach(el=>observer.observe(el));
document.addEventListener('keydown',e=>{if(e.key==='Escape'){menu.setAttribute('aria-expanded','false');document.querySelector('nav').classList.remove('open')}});
if('serviceWorker' in navigator)navigator.serviceWorker.register('sw.js');
